listing = boundary retry 3 {
    first = list_orders({ month: "2026-03", page: 1 })
    rest = for page in list.range(2, first.total_pages + 1) {
        r = boundary retry 3 { return list_orders({ month: "2026-03", page: page }) }
        return r.items
    }
    items = fold acc = first.items for page_items in rest { return acc + page_items }
    return items
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}

enriched = for order in listing {
    detail = boundary retry 3 { return get_order({ id: order.id }) } catch err {
        return fail("GET_ORDER_FAILED", err.code + ": " + err.message)
    }
    skip if detail.status != "completed"
    customer = boundary retry 3 { return get_customer({ id: order.customer_id }) } catch err {
        return fail("GET_CUSTOMER_FAILED", err.code + ": " + err.message)
    }
    return { region: customer.region, amount_cents: detail.amount_cents }
}

totals = fold acc = { NA: 0, EU: 0, APAC: 0 } for row in enriched {
    return acc + { [row.region]: acc[row.region] + row.amount_cents }
}

submission = submit_result({ answer: totals })
return { totals: totals, recorded: submission.recorded }

